import { z } from "zod";
import { PRODUCT_IDS } from "@notorganic/contracts";
import { CREDIT_PACK_CATALOG, GRANT_CATALOG } from "@notorganic/core";

export const WAITLIST_INTENTS = ["setup", "subscription", "credits"] as const;
export const waitlistSelectionSchema = z.object({
  product: z.enum(PRODUCT_IDS),
  intent: z.enum(WAITLIST_INTENTS),
  offerId: z.string().max(100).default(""),
}).superRefine((selection, ctx) => {
  if (!selection.offerId) return;
  const pack = CREDIT_PACK_CATALOG[selection.offerId as keyof typeof CREDIT_PACK_CATALOG];
  const grant = GRANT_CATALOG[selection.offerId as keyof typeof GRANT_CATALOG];
  const valid = selection.intent === "credits"
    ? pack?.product === selection.product
    : selection.intent === "subscription" && grant?.cadence === "monthly"
      && selection.offerId.startsWith(`${selection.product}_`);
  if (!valid) ctx.addIssue({ code: "custom", message: "Choose an offer for this service.", path: ["offerId"] });
});

export const purchaseWaitlistSchema = waitlistSelectionSchema.safeExtend({
  email: z.string().trim().toLowerCase().email().max(320),
});
export type WaitlistSelection = z.infer<typeof waitlistSelectionSchema>;
export type PurchaseWaitlistInput = z.infer<typeof purchaseWaitlistSchema>;
export interface PurchaseWaitlistEntry extends PurchaseWaitlistInput {
  id: string;
  createdAt: number;
  updatedAt: number;
}

export function purchaseWaitlistOfferLabel(selection: WaitlistSelection): string {
  const pack = CREDIT_PACK_CATALOG[selection.offerId as keyof typeof CREDIT_PACK_CATALOG];
  if (pack) return `$${pack.priceUsd} AI credit`;
  if (!selection.offerId) return "";
  return selection.offerId.slice(selection.product.length + 1).split("_")
    .filter(word => !/^v\d+$/.test(word))
    .map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(" ");
}
import { paginationOptsValidator } from "convex/server";
import { mutation, query } from "./_generated/server";
import { v } from "convex/values";
import { requirePortalSecret } from "./lib";
import { purchaseWaitlistSchema } from "../apps/portal/purchase-waitlist";

// Only the portal server can write submissions. Email is contact information,
// never evidence of account ownership or authority to grant access.
export const join = mutation({
  args: { portalSecret: v.string(), email: v.string(), product: v.string(), intent: v.string(), offerId: v.string() },
  returns: v.null(),
  handler: async (ctx, args) => {
    requirePortalSecret(args.portalSecret);
    const input = purchaseWaitlistSchema.parse(args);
    const existing = await ctx.db.query("purchaseWaitlist")
      .withIndex("by_request", q => q.eq("email", input.email).eq("product", input.product).eq("intent", input.intent).eq("offerId", input.offerId)).unique();
    if (existing) await ctx.db.patch(existing._id, { updatedAt: Date.now() });
    else await ctx.db.insert("purchaseWaitlist", { ...input, createdAt: Date.now(), updatedAt: Date.now() });
    return null;
  },
});

export const list = query({
  args: { portalSecret: v.string(), actorDid: v.string(), paginationOpts: paginationOptsValidator },
  returns: v.object({ page: v.array(v.object({ id: v.string(), email: v.string(), product: v.string(), intent: v.string(), offerId: v.string(), createdAt: v.number(), updatedAt: v.number() })), isDone: v.boolean(), continueCursor: v.string() }),
  handler: async (ctx, args) => {
    requirePortalSecret(args.portalSecret);
    if (!(process.env.NOTORGANIC_ADMIN_DIDS ?? "").split(",").map(value => value.trim()).filter(Boolean).includes(args.actorDid)) throw new Error("ADMIN_ACCESS_REQUIRED");
    const result = await ctx.db.query("purchaseWaitlist").withIndex("by_created").order("desc")
      .paginate({ ...args.paginationOpts, numItems: Math.min(50, Math.max(1, args.paginationOpts.numItems)) });
    return { page: result.page.map(({ _id, email, product, intent, offerId, createdAt, updatedAt }) => ({ id: String(_id), email, product, intent, offerId, createdAt, updatedAt })), isDone: result.isDone, continueCursor: result.continueCursor };
  },
});
