import { expect, test } from "bun:test";
import { createPortalApp, type PortalDependencies } from "./routes";

function fixture(fail = false) {
  const entries: unknown[] = [];
  const app = createPortalApp({
    config: { publicUrl: "https://id.notorganic.info", secureCookies: true }, oauth: {}, adapter: {},
    store: { joinPurchaseWaitlist: async (input: unknown) => { if (fail) throw new Error("private upstream details"); entries.push(input); } },
  } as unknown as PortalDependencies);
  return { app, entries };
}

async function form(app: ReturnType<typeof createPortalApp>, query = "product=twyne&intent=credits&offerId=twyne_credit_25") {
  const response = await app.request(`/waitlist?${query}`);
  const text = await response.text();
  const csrf = text.match(/name="csrf" value="([^"]+)"/)?.[1];
  return { response, text, csrf: csrf!, cookie: response.headers.get("set-cookie")!.split(";")[0]! };
}

test("public form preserves purchase intent without requiring an account or collecting payment", async () => {
  const { app, entries } = fixture();
  const { response, text } = await form(app);
  expect(response.status).toBe(200);
  expect(text).toContain("$25 AI credit");
  expect(text).toContain('name="offerId" value="twyne_credit_25"');
  expect(text).not.toContain("twyne credit 25");
  expect(response.headers.get("cache-control")).toBe("no-store");
  expect(entries).toHaveLength(0);
