  return html`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${joined ? "You're on the list" : "Join the waitlist"} · Not Organic</title><link rel="stylesheet" href="/waitlist.css"></head>
    <body><main><a class="brand" href="/">Not Organic</a><p class="service">${names[selection.product]}</p>
    <h1>${joined ? "You're on the list." : "Join the waitlist."}</h1>
    ${joined ? html`<p role="status">Your request for ${selection.intent === "credits" ? "AI credits" : selection.intent === "subscription" ? "a subscription" : "account setup"} is saved. We'll contact you about access. No payment was taken and no subscription was started.</p><a href="/waitlist?${new URLSearchParams(selection)}">Register another request</a>` : html`
    <p>Join the ${names[selection.product]} waitlist through Not Organic. Tell us what you'd like to use, and we'll contact you about access.</p>
    ${message ? html`<p class="error" role="alert">${message}</p>` : ""}
    <form method="post" action="/waitlist">
      <input type="hidden" name="csrf" value="${token}"><input type="hidden" name="product" value="${selection.product}">
      ${selection.offerId ? html`<input type="hidden" name="intent" value="${selection.intent}"><input type="hidden" name="offerId" value="${selection.offerId}"><p class="selection">${offerLabel}</p>` : html`<label>I'm interested in<select name="intent">${Object.entries(intents).map(([value, label]) => html`<option value="${value}"${value === selection.intent ? html` selected` : ""}>${label}</option>`)}</select></label>`}
      <label>Email address<input type="email" name="email" autocomplete="email" required maxlength="320" value="${email}"></label>
      <p class="note">We'll use your email to follow up on this request. Joining does not create an account, add credits, or start a paid plan.</p>
      <button type="submit">Join the waitlist</button>
    </form>`}
    <footer><a href="https://notorganic.info/privacy">Privacy</a><a href="/">Open your account</a></footer></main></body></html>`;
}

export function registerPurchaseWaitlist(app: Hono<{ Variables: { session: PortalSession } }>, store: PortalStore, config: { publicUrl: string; secureCookies: boolean }) {
  const allowed = createDiscoveryLimiter(8, 15 * 60_000);
  app.get("/waitlist.css", c => c.text(styles, 200, { "content-type": "text/css; charset=utf-8" }));
  app.use("/waitlist", bodyLimit({ maxSize: 4096 }));
  app.use("/waitlist", async (c, next) => { c.header("Cache-Control", "no-store"); c.header("Referrer-Policy", "no-referrer"); await next(); });
  app.get("/waitlist", c => {
    const result = waitlistSelectionSchema.safeParse({ ...c.req.query(), product: c.req.query("product") ?? "notorganic", intent: c.req.query("intent") ?? "setup" });
    if (!result.success) return c.text("This waitlist link is invalid. Return to the service and try again.", 400);
    const token = randomUUID();
    setCookie(c, COOKIE, token, { httpOnly: true, secure: config.secureCookies, sameSite: "Lax", path: "/waitlist", maxAge: 3600 });
    return c.html(page(result.data, token));
  });
  app.post("/waitlist", async c => {
    if (c.req.header("origin") !== new URL(config.publicUrl).origin) return c.text("Reload the waitlist form and try again.", 403);
    const body = await c.req.parseBody();
    const token = getCookie(c, COOKIE);
    if (!token || body.csrf !== token) return c.text("Reload the waitlist form and try again.", 403);
    const selection = waitlistSelectionSchema.safeParse(body);
    if (!selection.success) return c.text("Choose a valid service and offer.", 400);
    const input = purchaseWaitlistSchema.safeParse(body);
    if (!input.success) return c.html(page(selection.data, token, "Enter a valid email address."), 400);
    if (!allowed(c.req.header("x-forwarded-for")?.split(",")[0]?.trim() ?? "anonymous")) return c.html(page(selection.data, token, "Too many requests. Please try again in 15 minutes.", false, input.data.email), 429);
    try {
      if (!store.joinPurchaseWaitlist) throw new Error("WAITLIST_UNAVAILABLE");
      await store.joinPurchaseWaitlist(input.data);
      return c.html(page(selection.data, token, "", true));
    } catch {
      return c.html(page(selection.data, token, "We couldn't save your request. Please try again.", false, input.data.email), 503);
    }
  });
}

