  "../convex/purchaseWaitlist.ts": () => import("../convex/purchaseWaitlist"),
};
const join = makeFunctionReference<"mutation">("purchaseWaitlist:join");
const list = makeFunctionReference<"query">("purchaseWaitlist:list");
const portalSecret = "waitlist-test-secret", actorDid = "did:plc:admin";
const prior = { portal: process.env.CONVEX_PORTAL_SECRET, admin: process.env.NOTORGANIC_ADMIN_DIDS };
