afterAll(() => {
  for (const [key, value] of [["CONVEX_PORTAL_SECRET", prior.portal], ["NOTORGANIC_ADMIN_DIDS", prior.admin]] as const) {
    if (value === undefined) delete process.env[key]; else process.env[key] = value;
  }
});
