test("retrying an interest does not duplicate it; different packs and subscription interest remain distinct", async () => {
  const t = convexTest(schema, modules);
  await Promise.all([t.mutation(join, input), t.mutation(join, { ...input, email: "Writer@Example.test" })]);
  await t.mutation(join, { ...input, offerId: "twyne_credit_25" });
  await t.mutation(join, { ...input, intent: "subscription", offerId: "twyne_pro_v2" });
