const REQUIRED_SCOPES = [
  "wallet:read",
  "usage:read",
  "billing:checkout",
  "infer:balanced",
] as const;

export type PricingAvailability =
  | "unconfigured"
  | "connect_required"
  | "checkout";

export function isPublicCheckoutConfigured(
  env: Record<string, string | undefined>,
): boolean {
  const fieldsPresent = [
    env.VITE_NOTORGANIC_PUBLIC_ISSUER,
    env.VITE_NOTORGANIC_AUTHORIZATION_URL,
    env.VITE_NOTORGANIC_CLIENT_ID,
    env.VITE_NOTORGANIC_REDIRECT_URI,
    env.VITE_NOTORGANIC_SCOPE,
  ].every((value) => Boolean(value?.trim()));
  const scopes = new Set(env.VITE_NOTORGANIC_SCOPE?.trim().split(/\s+/) ?? []);
  return (
    env.VITE_NOTORGANIC_ENABLED === "true" &&
    fieldsPresent &&
    REQUIRED_SCOPES.every((scope) => scopes.has(scope))
  );
}

// Enable only after the provider maps every v2 plan to its own verified price.
// An existing deployment's authentication settings cannot enable new sales.
export function isSubscriptionCheckoutConfigured(
  env: Record<string, string | undefined>,
): boolean {
  return isPublicCheckoutConfigured(env) && env.VITE_NOTORGANIC_SUBSCRIPTION_CATALOG === "stich_v2";
}

export function pricingAvailability(
  checkoutConfigured: boolean,
  providerConnected: boolean,
): PricingAvailability {
  if (!checkoutConfigured) return "unconfigured";
  return providerConnected ? "checkout" : "connect_required";
}

export function walletSpendableMicros(wallet: {
  balanceMicros: number;
  availableGrantMicros: number;
  reservedMicros: number;
  debtMicros: number;
}): number {
  return Math.max(
    0,
    wallet.balanceMicros +
      wallet.availableGrantMicros -
      wallet.reservedMicros -
      wallet.debtMicros,
  );
}

