export class AccountNotFoundError extends Error {
  constructor() { super("No account matches that handle."); }
}

export interface AccountDiscovery {
  suggest(query: string, signal?: AbortSignal): Promise<AccountCandidate[]>;
  resolve(identifier: string, signal?: AbortSignal): Promise<ResolvedAccount>;
  avatar(did: string, cid: string, signal?: AbortSignal): Promise<Response | null>;
