/** The subset of `OAuthClient.oauthResolver` discovery depends on. */
export interface DiscoveryResolver {
  resolveFromIdentity(input: string, options?: { signal?: AbortSignal }): Promise<{
    identityInfo: { did: string; handle: string };
    metadata: { issuer: string };
    pds: URL;
  }>;
}

const DID = /^did:[a-z0-9]+:[A-Za-z0-9._:%-]+$/;
const CID = /^[a-z0-9]{20,120}$/;
const AVATAR_URL = /^https:\/\/cdn\.bsky\.app\/img\/avatar(?:_thumbnail)?\/plain\/(did:[a-z0-9]+:[A-Za-z0-9._:%-]+)\/([a-z0-9]{20,120})@jpeg$/;
