import { portalApi, PortalApiError } from "./api";
import type { PurchaseWaitlistEntry } from "../purchase-waitlist";
import type { AccountPage, AdminCreditCode, CreditCodeInput, CreditCodePage, CreditProductScope, DirectGrantInput, RedeemCreditResult } from "../access-management";
export type CreditCode = AdminCreditCode;

export interface WaitlistEntry {
  id: string;
  email: string;
  status: "pending" | "approved";
  approvedAt?: number;
}

/** Uses the portal session cookie and CSRF token; no operator credential enters the browser. */
async function request<T>(path: string, body?: unknown): Promise<T> {
  const session = body === undefined ? null : await portalApi.session();
  if (body !== undefined && !session) throw new PortalApiError("Sign in again to continue.", 401);
  const response = await fetch(path, {
    method: body === undefined ? "GET" : "POST",
    credentials: "same-origin",
    headers: {
      accept: "application/json",
      ...(body === undefined ? {} : { "content-type": "application/json", "x-csrf-token": session!.csrfToken }),
    },
    ...(body === undefined ? {} : { body: JSON.stringify(body) }),
  });
  let payload: unknown;
  try { payload = await response.json(); }
  catch { throw new PortalApiError("The server returned an unreadable response. Try again.", response.status); }
  if (!response.ok) {
    const error = (payload as { error?: { message?: string; code?: string } })?.error;
    throw new PortalApiError(error?.message ?? "This request could not be completed.", response.status, error?.code);
  }
  return payload as T;
}

function pagePath(path: string, cursor?: string | null) {
  return cursor ? `${path}?cursor=${encodeURIComponent(cursor)}` : path;
}

export const accessApi = {
  purchaseRequests: (cursor?: string | null) => request<{ page: PurchaseWaitlistEntry[]; isDone: boolean; continueCursor: string }>(pagePath("/api/admin/access/requests", cursor)),
  accounts: (cursor?: string | null) => request<AccountPage>(pagePath("/api/admin/access/accounts", cursor)),
  codes: (cursor?: string | null) => request<CreditCodePage>(pagePath("/api/admin/access/codes", cursor)),
  createCode: (input: CreditCodeInput) => request<{ code: string; entry: CreditCode }>("/api/admin/access/codes", input),
  revokeCode: (id: string, reason: string) => request(`/api/admin/access/codes/${encodeURIComponent(id)}/revoke`, { reason }),
  grant: (input: DirectGrantInput) => request("/api/admin/access/grants", input),
  waitlist: (cursor?: string | null) => request<{ data: WaitlistEntry[]; cursor?: string | null }>(pagePath("/api/admin/access/waitlist", cursor)),
  approveWaitlist: (id: string, input: { amountMicros: number; productScope: CreditProductScope; reason: string }) => request<{ code: string }>(`/api/admin/access/waitlist/${encodeURIComponent(id)}/approve`, input),
  redeem: (code: string) => request<RedeemCreditResult>("/api/credits/redeem", { code }),
};

export function creditAmount(value: string): number {
  if (!/^\d+(?:\.\d{1,2})?$/.test(value.trim())) throw new Error("Enter a dollar amount with up to two decimal places.");
  const amount = Math.round(Number(value) * 1_000_000);
  if (!Number.isSafeInteger(amount) || amount < 10_000 || amount > 1_000_000_000) throw new Error("Enter an amount from $0.01 to $1,000.");
  return amount;
}
import { createHash, randomBytes } from "node:crypto";
import type { Context, Hono } from "hono";
import { bodyLimit } from "hono/body-limit";
import type { PortalSession, PortalStore } from "./store";
import { overviewRange, type OverviewProduct } from "../admin-overview";
import { accessWaitlistConfigFromEnv, getWaitlistContact, listWaitlistContacts, WaitlistSourceError, type WaitlistConfig } from "./access-waitlist";

const hash = (value: string) => createHash("sha256").update(value).digest("hex");
const newCode = () => `NOU-${randomBytes(24).toString("base64url")}`;
const codeFields = ["label", "amountMicros", "productScope", "maxUses", "expiresAt", "grantExpiresAt", "reason"] as const;
type AccessContext = Context<{ Variables: { session: PortalSession } }>;

/** Registered after the existing session/admin/CSRF middleware. */
export function registerAccessRoutes(app: Hono<{ Variables: { session: PortalSession } }>, store: PortalStore, waitlist: WaitlistConfig = accessWaitlistConfigFromEnv()) {
  app.get("/api/admin/overview", async c => {
    c.header("Cache-Control", "private, no-store");
    const range = { start: c.req.query("start") ?? "", end: c.req.query("end") ?? "", product: (c.req.query("product") ?? "all") as OverviewProduct };
    try { overviewRange(range); } catch { return c.json({ error: { code: "invalid_range", message: "Choose a valid date range of up to 90 Toronto calendar days, ending no later than today." } }, 400); }
    if (!store.adminOverview) return c.json({ error: { code: "overview_unavailable", message: "Overview data is unavailable. The server query must be published before live figures can be shown." } }, 503);
    try { return c.json(await store.adminOverview(c.get("session").did, range)); }
    catch { return c.json({ error: { code: "overview_unavailable", message: "Overview data could not be loaded. Check the server query and source availability, then retry." } }, 503); }
  });
  app.use("/api/admin/access/*", bodyLimit({ maxSize: 8192 }));
  app.use("/api/credits/*", bodyLimit({ maxSize: 1024 }));
  app.use("/api/admin/access/*", async (c, next) => { c.header("Cache-Control", "private, no-store"); await next(); });
  app.use("/api/credits/*", async (c, next) => { c.header("Cache-Control", "private, no-store"); await next(); });

  async function input(c: AccessContext): Promise<Record<string, unknown>> {
    const body: unknown = await c.req.json();
    if (!body || typeof body !== "object" || Array.isArray(body)) throw new Error("INVALID_INPUT");
    return body as Record<string, unknown>;
  }

  async function result(c: AccessContext, operation: () => Promise<unknown>, message: string) {
    try { return c.json(await operation()); }
    catch (error) {
      if (error instanceof WaitlistSourceError) return Response.json({ error: { message: error.message } }, { status: error.status });
      // Provider errors may contain credentials or account internals. Give the
      // browser an actionable result without echoing upstream exception text.
      return c.json({ error: { message } }, 400);
    }
  }

  const actor = (c: AccessContext): string => c.get("session").did;
  const query = (c: AccessContext, operation: "listAccounts" | "listCodes" | "listApprovals", args: Record<string, unknown>) => {
    if (!store.accessQuery) throw new Error("ACCESS_UNAVAILABLE");
    return store.accessQuery(operation, actor(c), args);
  };
  const mutate = (c: AccessContext, operation: "createCode" | "revokeCode" | "directGrant" | "approveWaitlist", args: Record<string, unknown>) => {
    if (!store.accessMutation) throw new Error("ACCESS_UNAVAILABLE");
    return store.accessMutation(operation, actor(c), args);
  };

  app.get("/api/admin/access/accounts", c => result(c, () => query(c, "listAccounts", { paginationOpts: { cursor: c.req.query("cursor") ?? null, numItems: 50 } }), "Accounts could not be loaded. Try refreshing."));
  app.get("/api/admin/access/codes", c => result(c, () => query(c, "listCodes", { paginationOpts: { cursor: c.req.query("cursor") ?? null, numItems: 50 } }), "Credit codes could not be loaded. Try refreshing."));
  app.post("/api/admin/access/codes", c => result(c, async () => {
    const body = await input(c);
    const code = newCode();
    const entry = await mutate(c, "createCode", { ...Object.fromEntries(codeFields.map(field => [field, body[field]])), tokenHash: hash(code) });
    return { code, entry };
  }, "Code not created. Check its credit amount, uses, expiry and review note."));
  app.post("/api/admin/access/codes/:id/revoke", c => result(c, async () => {
    const body = await input(c);
    return mutate(c, "revokeCode", { codeId: c.req.param("id"), reason: body.reason });
  }, "Code could not be revoked. Include a review note and try again."));
  app.post("/api/admin/access/grants", c => result(c, async () => {
    const body = await input(c);
    return mutate(c, "directGrant", Object.fromEntries(["did", "amountMicros", "productScope", "grantExpiresAt", "requestId", "reason"].map(field => [field, body[field]])));
  }, "Credit not added. Check the account, finite amount and review note. Retry with the same request to avoid a duplicate grant."));

  app.post("/api/credits/redeem", c => result(c, async () => {
    const body = await input(c);
    if (typeof body.code !== "string" || !/^NOU-[A-Za-z0-9_-]{32}$/.test(body.code.trim())) throw new Error("INVALID_CODE");
    if (!store.redeemCreditCode) throw new Error("ACCESS_UNAVAILABLE");
    return store.redeemCreditCode(actor(c), hash(body.code.trim()));
  }, "This code could not be redeemed. Check the code; it may be expired, revoked or fully used."));

  app.get("/api/admin/access/waitlist", c => result(c, async () => {
    const page = await listWaitlistContacts(waitlist, c.req.query("cursor"));
    const approvals = await query(c, "listApprovals", { segmentId: waitlist.segmentId, contactIds: page.data.map(contact => contact.id) }) as Array<{ contactId: string; approvedAt: number }>;
    const byId = new Map(approvals.map(approval => [approval.contactId, approval]));
    return { data: page.data.map(contact => ({ ...contact, status: byId.has(contact.id) ? "approved" : "pending", ...(byId.has(contact.id) ? { approvedAt: byId.get(contact.id)!.approvedAt } : {}) })), cursor: page.nextCursor };
  }, "Waitlist could not be loaded. Check the server's waitlist configuration and try again."));
  app.post("/api/admin/access/waitlist/:id/approve", c => result(c, async () => {
    const body = await input(c);
    const contact = await getWaitlistContact(waitlist, c.req.param("id"));
    const code = newCode();
    const timestamp = Date.now();
    const entry = await mutate(c, "approveWaitlist", {
      contactId: contact.id, segmentId: contact.segmentId,
      emailHash: hash(contact.email.trim().toLowerCase()), tokenHash: hash(code),
      label: "Waitlist invitation", maxUses: 1, amountMicros: body.amountMicros, productScope: body.productScope,
      expiresAt: timestamp + 30 * 24 * 60 * 60_000, grantExpiresAt: null, reason: body.reason,
    });
    return { code, entry };
  }, "Approval not saved. This contact may already be approved or no longer be on the waitlist. Refresh before retrying."));
}

import { useEffect, useRef, useState } from "react";
import { usePostHog } from "@posthog/react";
import { DEFAULT_NOTORGANIC_PACK_ID, getNotOrganicPack, type NotOrganicPack, type NotOrganicPackId } from "../notorganic-provider/packs";
import "./credit-waitlist.css";

const CHANGE_EVENT = "keating:credit-waitlist-changed";


export type PricingWaitlistVariant = "control" | "test";
export type CreditWaitlistPanelState = "prompt" | "loading" | "success" | "error";

type CreditWaitlistRequest = {
	id: string;
	packId: NotOrganicPackId;
	pricingVariant: PricingWaitlistVariant;
};

let activeRequest: CreditWaitlistRequest | null = null;

export function getActiveCreditWaitlistRequest(): CreditWaitlistRequest | null {
	return activeRequest;
}

function emitChange() {
	window.dispatchEvent(new CustomEvent(CHANGE_EVENT));
}

/** Collect launch interest when hosted checkout is unavailable on this deployment. */
export function promptCreditWaitlist(
	packId: NotOrganicPackId = DEFAULT_NOTORGANIC_PACK_ID,
	pricingVariant: PricingWaitlistVariant = "control",
): void {
	if (typeof window === "undefined") return;
	activeRequest = { id: crypto.randomUUID(), packId, pricingVariant };
	emitChange();
}

export function closeCreditWaitlist(): void {
	if (!activeRequest) return;
	activeRequest = null;
	emitChange();
}

export function CreditWaitlistPanel({ pack, state, message, onJoin, onDismiss }: {
  pack: NotOrganicPack; state: CreditWaitlistPanelState; message?: string;
  onJoin(email: string, website: string): void; onDismiss(): void;
}) {
  const [email, setEmail] = useState("");
  const [consent, setConsent] = useState(false);
  const [website, setWebsite] = useState("");
  const panel = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const prior = document.activeElement as HTMLElement | null;
    panel.current?.querySelector<HTMLInputElement>("input[type=email]")?.focus();
    return () => prior?.focus();
  }, []);
  return <div ref={panel} role="dialog" aria-modal="true" aria-labelledby="credit-waitlist-title" className="credit-waitlist" onKeyDown={event => {
    if (event.key === "Escape") onDismiss();
    if (event.key === "Tab") {
      const items = panel.current?.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled):not([tabindex="-1"]), a[href]');
      if (!items?.length) return;
      const first = items[0]; const last = items[items.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    }
  }}>
    <header><h2 id="credit-waitlist-title">{state === "success" ? "You're on the list" : "Get the launch email"}</h2><button type="button" onClick={onDismiss} aria-label="Close waitlist">×</button></header>
    {state === "success" ? <div className="credit-waitlist__content"><p role="status">{message || "Your email is saved. We'll let you know when hosted credits are ready."}</p><button type="button" onClick={onDismiss}>Done</button></div> :
      <form className="credit-waitlist__content" onSubmit={event => { event.preventDefault(); if (consent && state !== "loading") onJoin(email, website); }}>
        <p>The <strong>{pack.label}</strong> pack (${pack.priceUsd}) isn't available to buy yet. Leave your email to hear when hosted credits launch. Nothing will be charged.</p>
