function usePages<T>(load: (cursor?: string | null) => Promise<Page<T>>) {
  const [rows, setRows] = useState<T[]>([]);
  const [cursor, setCursor] = useState<string | null>(null);
  const [busy, setBusy] = useState(true);
  const [error, setError] = useState("");
  const generation = useRef(0);
  const loadPage = useCallback(async (next?: string | null) => {
    const version = ++generation.current;
    setBusy(true); setError("");
    try {
      const page = await load(next);
      if (generation.current === version) { setRows(old => next ? [...old, ...page.rows] : page.rows); setCursor(page.cursor); }
    } catch (caught) { if (generation.current === version) setError(caught instanceof Error ? caught.message : "Could not load this list."); }
    finally { if (generation.current === version) setBusy(false); }
  }, [load]);
  useEffect(() => { void loadPage(); return () => { generation.current++; }; }, [loadPage]);
  return { rows, cursor, busy, error, refresh: () => loadPage(), more: () => loadPage(cursor) };
}

