/** Uses the portal session cookie and CSRF token; no operator credential enters the browser. */
async function request<T>(path: string, body?: unknown): Promise<T> {
  const session = body === undefined ? null : await portalApi.session();
  if (body !== undefined && !session) throw new PortalApiError("Sign in again to continue.", 401);
  const response = await fetch(path, {
    method: body === undefined ? "GET" : "POST",
    credentials: "same-origin",
    headers: {
      accept: "application/json",
      ...(body === undefined ? {} : { "content-type": "application/json", "x-csrf-token": session!.csrfToken }),
    },
    ...(body === undefined ? {} : { body: JSON.stringify(body) }),
  });
  let payload: unknown;
  try { payload = await response.json(); }
  catch { throw new PortalApiError("The server returned an unreadable response. Try again.", response.status); }
  if (!response.ok) {
    const error = (payload as { error?: { message?: string; code?: string } })?.error;
    throw new PortalApiError(error?.message ?? "This request could not be completed.", response.status, error?.code);
  }
  return payload as T;
}

function pagePath(path: string, cursor?: string | null) {
  return cursor ? `${path}?cursor=${encodeURIComponent(cursor)}` : path;
}

export const accessApi = {
  purchaseRequests: (cursor?: string | null) => request<{ page: PurchaseWaitlistEntry[]; isDone: boolean; continueCursor: string }>(pagePath("/api/admin/access/requests", cursor)),
  accounts: (cursor?: string | null) => request<AccountPage>(pagePath("/api/admin/access/accounts", cursor)),
  codes: (cursor?: string | null) => request<CreditCodePage>(pagePath("/api/admin/access/codes", cursor)),
  createCode: (input: CreditCodeInput) => request<{ code: string; entry: CreditCode }>("/api/admin/access/codes", input),
  revokeCode: (id: string, reason: string) => request(`/api/admin/access/codes/${encodeURIComponent(id)}/revoke`, { reason }),
  grant: (input: DirectGrantInput) => request("/api/admin/access/grants", input),
  waitlist: (cursor?: string | null) => request<{ data: WaitlistEntry[]; cursor?: string | null }>(pagePath("/api/admin/access/waitlist", cursor)),
  approveWaitlist: (id: string, input: { amountMicros: number; productScope: CreditProductScope; reason: string }) => request<{ code: string }>(`/api/admin/access/waitlist/${encodeURIComponent(id)}/approve`, input),
  redeem: (code: string) => request<RedeemCreditResult>("/api/credits/redeem", { code }),
};

export function creditAmount(value: string): number {
  if (!/^\d+(?:\.\d{1,2})?$/.test(value.trim())) throw new Error("Enter a dollar amount with up to two decimal places.");
  const amount = Math.round(Number(value) * 1_000_000);
  if (!Number.isSafeInteger(amount) || amount < 10_000 || amount > 1_000_000_000) throw new Error("Enter an amount from $0.01 to $1,000.");
  return amount;
}
import { createHash, randomBytes } from "node:crypto";
